  1→import { useState } from "react";
  2→import { useQuery } from "@tanstack/react-query";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import { useAuth } from "@/hooks/useAuth";
  5→import {
  6→  Dialog,
  7→  DialogContent,
  8→  DialogDescription,
  9→  DialogHeader,
 10→  DialogTitle,
 11→  DialogTrigger,
 12→} from "@/components/ui/dialog";
 13→import { Button } from "@/components/ui/button";
 14→import { Badge } from "@/components/ui/badge";
 15→import { toast } from "sonner";
 16→import { Coins, Loader2, ShoppingCart, Sparkles, Crown, Gift } from "lucide-react";
 17→import SubscriptionDialog from "@/components/SubscriptionDialog";
 18→
 19→interface BuyCreditsDialogProps {
 20→  trigger?: React.ReactNode;
 21→}
 22→
 23→const BuyCreditsDialog = ({ trigger }: BuyCreditsDialogProps) => {
 24→  const { user, refreshProfile } = useAuth();
 25→  const [open, setOpen] = useState(false);
 26→  const [buying, setBuying] = useState<string | null>(null);
 27→
 28→  const { data: packs } = useQuery({
 29→    queryKey: ["credit_packs_active"],
 30→    queryFn: async () => {
 31→      const { data, error } = await supabase
 32→        .from("credit_packs")
 33→        .select("*")
 34→        .eq("active", true)
 35→        .order("price");
 36→      if (error) throw error;
 37→      return data;
 38→    },
 39→  });
 40→
 41→  const { data: hasPaidPayments } = useQuery({
 42→    queryKey: ["user_has_paid_payments", user?.id],
 43→    enabled: !!user,
 44→    queryFn: async () => {
 45→      const { count, error } = await supabase
 46→        .from("payments")
 47→        .select("id", { count: "exact", head: true })
 48→        .eq("user_id", user!.id)
 49→        .eq("status", "paid");
 50→      if (error) throw error;
 51→      return (count ?? 0) > 0;
 52→    },
 53→  });
 54→
 55→  const isTrialEligible = hasPaidPayments === false;
 56→
 57→  const visiblePacks = packs?.filter((p: any) => {
 58→    if (p.is_trial && !isTrialEligible) return false;
 59→    return true;
 60→  });
 61→
 62→  const trialPack = visiblePacks?.find((p: any) => p.is_trial);
 63→  const regularPacks = visiblePacks?.filter((p: any) => !p.is_trial);
 64→
 65→  const handleBuy = async (packId: string) => {
 66→    if (!user) return;
 67→    setBuying(packId);
 68→
 69→    try {
 70→      const { data, error } = await supabase.functions.invoke("create-dodo-checkout", {
 71→        body: {
 72→          pack_id: packId,
 73→          return_url: `${window.location.origin}/payment/callback`,
 74→        },
 75→      });
 76→
 77→      if (error) throw error;
 78→
 79→      if (!data?.checkout_url) {
 80→        toast.error(data?.error || "Failed to create checkout session");
 81→        return;
 82→      }
 83→
 84→      // Redirect to Dodo hosted checkout
 85→      window.location.href = data.checkout_url;
 86→    } catch (err: any) {
 87→      toast.error(err.message);
 88→    } finally {
 89→      setBuying(null);
 90→    }
 91→  };
 92→
 93→  return (
 94→    <Dialog open={open} onOpenChange={setOpen}>
 95→      <DialogTrigger asChild>
 96→        {trigger || (
 97→          <Button variant="outline" className="gap-2">
 98→            <ShoppingCart className="h-4 w-4" />
 99→            Buy Credits
100→          </Button>
101→        )}
102→      </DialogTrigger>
103→      <DialogContent className="sm:max-w-md">
104→        <DialogHeader>
105→          <DialogTitle className="flex items-center gap-2">
106→            <Sparkles className="h-5 w-5 text-primary" />
107→            Buy Credit Packs
108→          </DialogTitle>
109→          <DialogDescription>
110→            Purchase credits to rank more resumes. Credits never expire.
111→          </DialogDescription>
112→        </DialogHeader>
113→        <div className="space-y-3 pt-2">
114→          {trialPack && (
115→            <div className="relative rounded-xl p-[2px] bg-gradient-to-r from-primary via-amber-500 to-primary animate-pulse-slow">
116→              <div className="rounded-[10px] bg-background p-4">
117→                <div className="flex items-center gap-2 mb-2">
118→                  <Gift className="h-5 w-5 text-amber-500" />
119→                  <Badge className="bg-gradient-to-r from-primary to-amber-500 text-primary-foreground border-0 text-xs">
120→                    🎁 Welcome Offer
121→                  </Badge>
122→                  <Badge variant="outline" className="text-[10px] text-muted-foreground">
123→                    First purchase only
124→                  </Badge>
125→                </div>
126→                <div className="flex items-center justify-between">
127→                  <div>
128→                    <p className="font-semibold text-foreground text-base">{trialPack.name}</p>
129→                    <div className="flex items-center gap-2 mt-1">
130→                      <Badge variant="secondary" className="gap-1">
131→                        <Coins className="h-3 w-3" />
132→                        {trialPack.credits} credits
133→                      </Badge>
134→                    </div>
135→                    <p className="text-[11px] text-muted-foreground mt-1.5">
136→                      Try before you commit — this offer won't appear again
137→                    </p>
138→                  </div>
139→                  <Button
140→                    size="sm"
141→                    className="bg-gradient-to-r from-primary to-amber-500 hover:from-primary/90 hover:to-amber-500/90 text-primary-foreground font-bold"
142→                    onClick={() => handleBuy(trialPack.id)}
143→                    disabled={buying === trialPack.id}
144→                  >
145→                    {buying === trialPack.id ? (
146→                      <Loader2 className="h-4 w-4 animate-spin mr-1" />
147→                    ) : null}
148→                    {trialPack.price === 0 ? "Free" : `$${trialPack.price}`}
149→                  </Button>
150→                </div>
151→              </div>
152→            </div>
153→          )}
154→
155→          {regularPacks?.map((pack: any) => (
156→            <div
157→              key={pack.id}
158→              className="flex items-center justify-between rounded-lg border border-border p-4 hover:bg-accent/50 transition-colors"
159→            >
160→              <div>
161→                <p className="font-medium text-foreground">{pack.name}</p>
162→                <div className="flex items-center gap-2 mt-1">
163→                  <Badge variant="secondary" className="gap-1">
164→                    <Coins className="h-3 w-3" />
165→                    {pack.credits} credits
166→                  </Badge>
167→                </div>
168→              </div>
169→              <Button
170→                size="sm"
171→                onClick={() => handleBuy(pack.id)}
172→                disabled={buying === pack.id}
173→              >
174→                {buying === pack.id ? (
175→                  <Loader2 className="h-4 w-4 animate-spin mr-1" />
176→                ) : null}
177→                ${pack.price}
178→              </Button>
179→            </div>
180→          ))}
181→          {(!visiblePacks || visiblePacks.length === 0) && (
182→            <p className="text-sm text-muted-foreground text-center py-4">
183→              No credit packs available right now.
184→            </p>
185→          )}
186→        </div>
187→        <div className="rounded-lg bg-primary/5 border border-primary/20 px-4 py-3 flex items-center justify-between">
188→          <div className="flex items-center gap-2">
189→            <Crown className="h-4 w-4 text-primary" />
190→            <p className="text-xs font-medium text-foreground">Save more with a subscription plan</p>
191→          </div>
192→          <SubscriptionDialog
193→            trigger={
194→              <Button variant="ghost" size="sm" className="h-7 text-xs text-primary hover:text-primary gap-1">
195→                View Plans →
196→              </Button>
197→            }
198→          />
199→        </div>
200→      </DialogContent>
201→    </Dialog>
202→  );
203→};
204→
205→export default BuyCreditsDialog;
206→

  1→import { useState } from "react";
  2→import { useQuery } from "@tanstack/react-query";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import { useAuth } from "@/hooks/useAuth";
  5→import {
  6→  Dialog,
  7→  DialogContent,
  8→  DialogDescription,
  9→  DialogHeader,
 10→  DialogTitle,
 11→  DialogTrigger,
 12→} from "@/components/ui/dialog";
 13→import {
 14→  AlertDialog,
 15→  AlertDialogAction,
 16→  AlertDialogCancel,
 17→  AlertDialogContent,
 18→  AlertDialogDescription,
 19→  AlertDialogFooter,
 20→  AlertDialogHeader,
 21→  AlertDialogTitle,
 22→} from "@/components/ui/alert-dialog";
 23→import { Button } from "@/components/ui/button";
 24→import { Badge } from "@/components/ui/badge";
 25→import { toast } from "sonner";
 26→import { Crown, Loader2, Sparkles, Zap, Check, ArrowRight, ArrowDown, CalendarClock, XCircle } from "lucide-react";
 27→import { format } from "date-fns";
 28→
 29→interface SubscriptionDialogProps {
 30→  trigger?: React.ReactNode;
 31→}
 32→
 33→const SubscriptionDialog = ({ trigger }: SubscriptionDialogProps) => {
 34→  const { user, profile, refreshProfile } = useAuth();
 35→  const [open, setOpen] = useState(false);
 36→  const [buying, setBuying] = useState<string | null>(null);
 37→  const [cancelling, setCancelling] = useState(false);
 38→  const [confirmAction, setConfirmAction] = useState<{
 39→    type: "upgrade" | "downgrade" | "cancel_subscription";
 40→    planId?: string;
 41→    planName?: string;
 42→    price?: number;
 43→  } | null>(null);
 44→  const [downgrading, setDowngrading] = useState(false);
 45→
 46→  const currentPlan = profile?.plan ?? "free";
 47→  const isPaid = currentPlan !== "free";
 48→  const subscriptionEndsAt = (profile as any)?.subscription_ends_at
 49→    ? new Date((profile as any).subscription_ends_at)
 50→    : null;
 51→  const isExpired = subscriptionEndsAt ? subscriptionEndsAt < new Date() : false;
 52→  const hasActiveDodoSub = !!(profile as any)?.dodo_subscription_id;
 53→  const hasActiveRazorpaySub = !!(profile as any)?.razorpay_subscription_id;
 54→  const hasActiveSubscription = hasActiveDodoSub || hasActiveRazorpaySub;
 55→
 56→  const { data: plans } = useQuery({
 57→    queryKey: ["subscription_plans_active"],
 58→    queryFn: async () => {
 59→      const { data, error } = await supabase
 60→        .from("plans")
 61→        .select("*")
 62→        .eq("active", true)
 63→        .order("price");
 64→      if (error) throw error;
 65→      return data;
 66→    },
 67→  });
 68→
 69→  const { data: config } = useQuery({
 70→    queryKey: ["platform_config_payg"],
 71→    queryFn: async () => {
 72→      const { data, error } = await supabase
 73→        .from("platform_config")
 74→        .select("*")
 75→        .limit(1)
 76→        .single();
 77→      if (error) return null;
 78→      return data;
 79→    },
 80→  });
 81→
 82→  const paygCost = (config as any)?.payg_per_resume_cost ?? 0.07;
 83→
 84→  const handleSubscribe = async (planId: string) => {
 85→    if (!user) return;
 86→    setBuying(planId);
 87→
 88→    try {
 89→      const { data, error } = await supabase.functions.invoke("create-dodo-checkout", {
 90→        body: {
 91→          plan_id: planId,
 92→          return_url: `${window.location.origin}/payment/callback`,
 93→        },
 94→      });
 95→
 96→      if (error) throw error;
 97→
 98→      if (!data?.checkout_url) {
 99→        toast.error(data?.error || "Failed to create checkout session");
100→        return;
101→      }
102→
103→      // Redirect to Dodo hosted checkout
104→      window.location.href = data.checkout_url;
105→    } catch (err: any) {
106→      toast.error(err.message);
107→    } finally {
108→      setBuying(null);
109→    }
110→  };
111→
112→  const handleCancelSubscription = async () => {
113→    setCancelling(true);
114→    try {
115→      if (hasActiveDodoSub) {
116→        const { error } = await supabase.functions.invoke("cancel-dodo-subscription", {});
117→        if (error) throw error;
118→      } else if (hasActiveRazorpaySub) {
119→        const { error } = await supabase.functions.invoke("cancel-razorpay-subscription", {});
120→        if (error) throw error;
121→      }
122→      toast.success("Subscription will cancel at the end of your current billing period.");
123→      await refreshProfile();
124→      setConfirmAction(null);
125→    } catch (err: any) {
126→      toast.error("Failed to cancel: " + err.message);
127→    } finally {
128→      setCancelling(false);
129→    }
130→  };
131→
132→  const handleDowngradeToPayg = async () => {
133→    setDowngrading(true);
134→    try {
135→      if (hasActiveDodoSub) {
136→        const { error: cancelError } = await supabase.functions.invoke("cancel-dodo-subscription", {});
137→        if (cancelError) console.error("Failed to cancel Dodo subscription:", cancelError);
138→      } else if (hasActiveRazorpaySub) {
139→        const { error: cancelError } = await supabase.functions.invoke("cancel-razorpay-subscription", {});
140→        if (cancelError) console.error("Failed to cancel Razorpay subscription:", cancelError);
141→      }
142→      const { error } = await supabase
143→        .from("profiles")
144→        .update({ plan: "free", subscription_ends_at: null, razorpay_subscription_id: null, dodo_subscription_id: null } as any)
145→        .eq("user_id", user?.id);
146→      if (error) throw error;
147→      toast.success("Switched to Pay As You Go. Your remaining credits are preserved.");
148→      await refreshProfile();
149→      setConfirmAction(null);
150→    } catch (err: any) {
151→      toast.error("Failed to downgrade: " + err.message);
152→    } finally {
153→      setDowngrading(false);
154→    }
155→  };
156→
157→  const handleConfirmedAction = () => {
158→    if (!confirmAction) return;
159→    if (confirmAction.type === "upgrade" && confirmAction.planId) {
160→      handleSubscribe(confirmAction.planId);
161→      setConfirmAction(null);
162→    } else if (confirmAction.type === "downgrade") {
163→      handleDowngradeToPayg();
164→    } else if (confirmAction.type === "cancel_subscription") {
165→      handleCancelSubscription();
166→    }
167→  };
168→
169→  return (
170→    <>
171→      <Dialog open={open} onOpenChange={setOpen}>
172→        <DialogTrigger asChild>
173→          {trigger || (
174→            <Button variant="outline" size="sm" className="gap-1.5">
175→              <Crown className="h-3.5 w-3.5" />
176→              Upgrade Plan
177→            </Button>
178→          )}
179→        </DialogTrigger>
180→        <DialogContent className="sm:max-w-lg">
181→          <DialogHeader>
182→            <DialogTitle className="flex items-center gap-2">
183→              <Sparkles className="h-5 w-5 text-primary" />
184→              Choose Your Plan
185→            </DialogTitle>
186→            <DialogDescription>
187→              {isPaid
188→                ? "Manage your subscription or switch plans."
189→                : "Upgrade to save on every resume ranked. All plans auto-renew."}
190→            </DialogDescription>
191→          </DialogHeader>
192→
193→          {/* Current Plan Banner */}
194→          <div className="rounded-lg border border-border bg-muted/50 px-4 py-3 flex items-center gap-3">
195→            <div className="flex h-8 w-8 items-center justify-center rounded-full bg-primary/15">
196→              {isPaid ? <Crown className="h-4 w-4 text-primary" /> : <Zap className="h-4 w-4 text-primary" />}
197→            </div>
198→            <div className="flex-1">
199→              <p className="text-sm font-medium text-foreground">
200→                Current: {isPaid ? currentPlan : "Pay As You Go"}
201→              </p>
202→              <p className="text-xs text-muted-foreground">
203→                {isPaid
204→                  ? subscriptionEndsAt
205→                    ? isExpired
206→                      ? "Your subscription has expired"
207→                      : hasActiveSubscription
208→                        ? `Auto-renews ${format(subscriptionEndsAt, "MMM d, yyyy")}`
209→                        : `Expires ${format(subscriptionEndsAt, "MMM d, yyyy")}`
210→                    : "You're saving on every resume!"
211→                  : `$${paygCost}/resume • Upgrade to save more`}
212→              </p>
213→            </div>
214→            {isPaid && subscriptionEndsAt && !isExpired && (
215→              <Badge variant="secondary" className="text-xs gap-1">
216→                <CalendarClock className="h-3 w-3" />
217→                {format(subscriptionEndsAt, "MMM d")}
218→              </Badge>
219→            )}
220→            {isPaid && isExpired && (
221→              <Badge variant="destructive" className="text-xs">Expired</Badge>
222→            )}
223→            {!isPaid && (
224→              <Badge variant="secondary" className="text-xs">Active</Badge>
225→            )}
226→          </div>
227→
228→          {/* Cancel Subscription Button */}
229→          {isPaid && hasActiveSubscription && !isExpired && (
230→            <Button
231→              variant="outline"
232→              size="sm"
233→              className="gap-1.5 text-xs border-destructive/30 text-destructive hover:bg-destructive/10"
234→              onClick={() => setConfirmAction({ type: "cancel_subscription" })}
235→              disabled={cancelling}
236→            >
237→              {cancelling ? <Loader2 className="h-3 w-3 animate-spin" /> : <XCircle className="h-3 w-3" />}
238→              Cancel Auto-Renewal
239→            </Button>
240→          )}
241→
242→          {/* PAYG Card */}
243→          <div className={`rounded-lg border p-4 ${!isPaid ? "border-primary/50 bg-primary/5" : "border-border"}`}>
244→            <div className="flex items-center justify-between">
245→              <div>
246→                <div className="flex items-center gap-2">
247→                  <p className="font-semibold text-foreground">Pay As You Go</p>
248→                  {!isPaid && <Badge variant="default" className="text-[10px] px-1.5 py-0">Current</Badge>}
249→                </div>
250→                <p className="text-xs text-muted-foreground mt-1">No commitment • Buy credits anytime</p>
251→              </div>
252→              <div className="flex items-center gap-3">
253→                <div className="text-right">
254→                  <p className="text-lg font-bold text-foreground">$0</p>
255→                  <p className="text-xs text-muted-foreground">/month</p>
256→                </div>
257→                {isPaid && (
258→                  <Button
259→                    variant="outline"
260→                    size="sm"
261→                    className="gap-1 h-8 text-xs border-destructive/30 text-destructive hover:bg-destructive/10 hover:text-destructive"
262→                    onClick={() => setConfirmAction({ type: "downgrade" })}
263→                  >
264→                    <ArrowDown className="h-3 w-3" />
265→                    Switch
266→                  </Button>
267→                )}
268→              </div>
269→            </div>
270→            <div className="mt-3 flex items-center gap-4 text-xs text-muted-foreground">
271→              <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> ${paygCost}/resume</span>
272→              <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> Credit top-ups</span>
273→            </div>
274→          </div>
275→
276→          {/* Subscription Plans */}
277→          <div className="space-y-3">
278→            {plans?.map((plan: any, idx: number) => {
279→              const isCurrentPlan = currentPlan === plan.name;
280→              const savings = paygCost > 0 ? Math.round(((paygCost - (plan.per_resume_cost ?? 0.05)) / paygCost) * 100) : 0;
281→              const isPopular = idx === Math.floor((plans.length - 1) / 2);
282→
283→              return (
284→                <div
285→                  key={plan.id}
286→                  className={`relative rounded-lg border p-4 transition-colors ${
287→                    isCurrentPlan
288→                      ? "border-primary/50 bg-primary/5"
289→                      : "border-border hover:border-primary/30 hover:bg-accent/30"
290→                  }`}
291→                >
292→                  {isPopular && !isCurrentPlan && (
293→                    <Badge className="absolute -top-2.5 right-3 bg-primary text-primary-foreground text-[10px] px-2 py-0.5">
294→                      Popular
295→                    </Badge>
296→                  )}
297→                  <div className="flex items-center justify-between">
298→                    <div>
299→                      <div className="flex items-center gap-2">
300→                        <p className="font-semibold text-foreground">{plan.name}</p>
301→                        {isCurrentPlan && <Badge variant="default" className="text-[10px] px-1.5 py-0">Current</Badge>}
302→                        {savings > 0 && !isCurrentPlan && (
303→                          <Badge variant="secondary" className="text-[10px] px-1.5 py-0 text-primary">
304→                            Save {savings}%
305→                          </Badge>
306→                        )}
307→                      </div>
308→                      <p className="text-xs text-muted-foreground mt-1">
309→                        {plan.billing_type} • {plan.credits} credits • Auto-renews
310→                      </p>
311→                    </div>
312→                    <div className="text-right">
313→                      <p className="text-lg font-bold text-foreground">${plan.price}</p>
314→                      <p className="text-xs text-muted-foreground">/{plan.billing_type === "yearly" ? "year" : "mo"}</p>
315→                    </div>
316→                  </div>
317→                  <div className="mt-3 flex items-center justify-between">
318→                    <div className="flex items-center gap-4 text-xs text-muted-foreground">
319→                      <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> ${plan.per_resume_cost ?? 0.05}/resume</span>
320→                      <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> Credit top-ups</span>
321→                    </div>
322→                    {!isCurrentPlan && (
323→                      <Button
324→                        size="sm"
325→                        onClick={() =>
326→                          setConfirmAction({
327→                            type: "upgrade",
328→                            planId: plan.id,
329→                            planName: plan.name,
330→                            price: plan.price,
331→                          })
332→                        }
333→                        disabled={buying === plan.id}
334→                        className="gap-1 h-8"
335→                      >
336→                        {buying === plan.id ? (
337→                          <Loader2 className="h-3.5 w-3.5 animate-spin" />
338→                        ) : (
339→                          <>
340→                            Subscribe <ArrowRight className="h-3 w-3" />
341→                          </>
342→                        )}
343→                      </Button>
344→                    )}
345→                  </div>
346→                </div>
347→              );
348→            })}
349→            {(!plans || plans.length === 0) && (
350→              <p className="text-sm text-muted-foreground text-center py-4">
351→                No subscription plans available right now.
352→              </p>
353→            )}
354→          </div>
355→
356→          <p className="text-[11px] text-muted-foreground text-center pt-1">
357→            All plans auto-renew. Cancel anytime before your next billing date.
358→          </p>
359→        </DialogContent>
360→      </Dialog>
361→
362→      {/* Confirmation AlertDialog */}
363→      <AlertDialog open={confirmAction !== null} onOpenChange={(o) => !o && setConfirmAction(null)}>
364→        <AlertDialogContent>
365→          <AlertDialogHeader>
366→            <AlertDialogTitle>
367→              {confirmAction?.type === "upgrade"
368→                ? `Subscribe to ${confirmAction.planName}?`
369→                : confirmAction?.type === "cancel_subscription"
370→                  ? "Cancel Auto-Renewal?"
371→                  : "Switch to Pay As You Go?"}
372→            </AlertDialogTitle>
373→            <AlertDialogDescription>
374→              {confirmAction?.type === "upgrade" ? (
375→                <>
376→                  You'll be redirected to our secure checkout page to complete payment of{" "}
377→                  <span className="font-semibold text-foreground">${confirmAction.price}</span>.
378→                  Your subscription will auto-renew each billing period.
379→                </>
380→              ) : confirmAction?.type === "cancel_subscription" ? (
381→                <>
382→                  Your subscription will remain active until the end of your current billing period.
383→                  After that, you'll be switched to Pay As You Go pricing. Your remaining credits will be preserved.
384→                </>
385→              ) : (
