 21→    queryFn: async () => {
 22→      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
 23→      if (error) throw error;
 24→      const map: Record<string, string> = {};
 25→      (data as any[])?.forEach((u) => { map[u.id] = u.email; });
 26→      return map;
 27→    },
 28→    staleTime: 5 * 60 * 1000,
 29→  });
 30→
 31→  const { data, isLoading } = useQuery({
 32→    queryKey: ["admin_payments", page],
 33→    queryFn: async () => {
 34→      const from = page * PAGE_SIZE;
 35→      const to = from + PAGE_SIZE - 1;
 36→      const { data, error, count } = await supabase
 37→        .from("payments")
 38→        .select("*", { count: "exact" })
 39→        .order("created_at", { ascending: false })
 40→        .range(from, to);
 41→      if (error) throw error;
 42→      return { payments: data, total: count ?? 0 };
 43→    },
 44→  });
