 61→        price: parseFloat(form.price),
 62→        credits: parseInt(form.credits),
 63→        billing_type: form.billing_type,
 64→        active: form.active,
 65→        per_resume_cost: parseFloat(form.per_resume_cost),
 66→        dodo_product_id: form.dodo_product_id.trim() || null,
 67→        ...(priceChanged ? { razorpay_plan_id: null } : {}),
 68→      } as any;
 69→
 70→      if (editPlan === "new") {
 71→        const { error } = await supabase.from("plans").insert(payload);
 72→        if (error) { toast.error(error.message); return; }
 73→      } else {
 74→        const { error } = await supabase.from("plans").update(payload).eq("id", editPlan.id);
 75→        if (error) { toast.error(error.message); return; }
 76→        if (priceChanged) toast.info("Price changed — Razorpay sync required");
 77→      }
 78→      toast.success("Plan saved");
 79→      logAuditAction(
 80→        editPlan === "new" ? "plan.create" : "plan.update",
 81→        "plan",
 82→        editPlan === "new" ? undefined : editPlan.id,
 83→        { name: form.name, price: form.price, credits: form.credits },
 84→      );
 85→      qc.invalidateQueries({ queryKey: ["admin_plans"] });
 86→      setEditPlan(null);
 87→    } finally {
 88→      setSaving(false);
 89→    }
