 32→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
 33→        status: 401,
 34→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 35→      });
 36→    }
 37→    const userId = claimsData.claims.sub;
 38→
 39→    const { pack_id, plan_id } = await req.json();
 40→
 41→    let amount = 0;
 42→    let credits = 0;
 43→    let currency = "USD";
 44→
 45→    const serviceClient = createClient(
 46→      Deno.env.get("SUPABASE_URL")!,
 47→      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
 48→    );
 49→
 50→    if (pack_id) {
 51→      const { data: pack, error } = await serviceClient
 52→        .from("credit_packs")
