 56→        .single();
 57→      if (error || !pack) {
 58→        return new Response(JSON.stringify({ error: "Pack not found" }), {
 59→          status: 400,
 60→          headers: { ...corsHeaders, "Content-Type": "application/json" },
 61→        });
 62→      }
 63→
 64→      // Trial pack server-side guard
 65→      if (pack.is_trial) {
 66→        const { count } = await serviceClient
 67→          .from("payments")
 68→          .select("id", { count: "exact", head: true })
 69→          .eq("user_id", userId)
 70→          .eq("status", "paid");
 71→        if ((count ?? 0) > 0) {
 72→          return new Response(JSON.stringify({ error: "Trial pack is no longer available" }), {
 73→            status: 403,
 74→            headers: { ...corsHeaders, "Content-Type": "application/json" },
 75→          });
 76→        }
 77→      }
 78→
 79→      amount = Math.round(pack.price * 100);
 80→      credits = pack.credits;
 81→    } else if (plan_id) {
 82→      const { data: plan, error } = await serviceClient
 83→        .from("plans")
 84→        .select("price, credits")
 85→        .eq("id", plan_id)
 86→        .eq("active", true)
 87→        .single();
 88→      if (error || !plan) {
 89→        return new Response(JSON.stringify({ error: "Plan not found" }), {
 90→          status: 400,
 91→          headers: { ...corsHeaders, "Content-Type": "application/json" },
 92→        });
 93→      }
 94→      amount = Math.round(plan.price * 100);
 95→      credits = plan.credits;
 96→    } else {
 97→      return new Response(JSON.stringify({ error: "pack_id or plan_id required" }), {
 98→        status: 400,
 99→        headers: { ...corsHeaders, "Content-Type": "application/json" },
100→      });
101→    }
102→
103→    // Create Razorpay order
104→    const razorpayKeyId = Deno.env.get("RAZORPAY_KEY_ID")!;
105→    const razorpayKeySecret = Deno.env.get("RAZORPAY_KEY_SECRET")!;
106→
107→    const razorpayRes = await fetch("https://api.razorpay.com/v1/orders", {
108→      method: "POST",
109→      headers: {
110→        "Content-Type": "application/json",
111→        Authorization: "Basic " + btoa(`${razorpayKeyId}:${razorpayKeySecret}`),
112→      },
113→      body: JSON.stringify({ amount, currency, receipt: `pay_${Date.now()}` }),
114→    });
115→
116→    const razorpayOrder = await razorpayRes.json();
117→    if (!razorpayRes.ok) {
118→      console.error("Razorpay error:", razorpayOrder);
119→      return new Response(JSON.stringify({ error: "Failed to create order" }), {
120→        status: 500,
121→        headers: { ...corsHeaders, "Content-Type": "application/json" },
122→      });
123→    }
124→
125→    // Insert payment record
126→    await serviceClient.from("payments").insert({
127→      user_id: userId,
128→      razorpay_order_id: razorpayOrder.id,
129→      amount,
130→      currency,
131→      credits_purchased: credits,
132→      pack_id: pack_id || null,
133→      plan_id: plan_id || null,
134→      status: "created",
135→    });
136→
137→    return new Response(
138→      JSON.stringify({
139→        order_id: razorpayOrder.id,
140→        amount,
141→        currency,
142→        razorpay_key_id: razorpayKeyId,
143→      }),
144→      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
145→    );
146→  } catch (err: unknown) {
147→    console.error("Error:", err);
148→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
149→      status: 500,
150→      headers: { ...corsHeaders, "Content-Type": "application/json" },
151→    });
152→  }
