  9→async function verifySignature(
 10→  orderId: string,
 11→  paymentId: string,
 12→  signature: string,
 13→  secret: string
 14→): Promise<boolean> {
 15→  const enc = new TextEncoder();
 16→  const key = await crypto.subtle.importKey(
 17→    "raw",
 18→    enc.encode(secret),
 19→    { name: "HMAC", hash: "SHA-256" },
 20→    false,
 21→    ["sign"]
 22→  );
 23→  const data = enc.encode(`${orderId}|${paymentId}`);
 24→  const sig = await crypto.subtle.sign("HMAC", key, data);
 25→  const hex = Array.from(new Uint8Array(sig))
 26→    .map((b) => b.toString(16).padStart(2, "0"))
 27→    .join("");
 28→  return hex === signature;
 29→}
