 31→Deno.serve(async (req) => {
 32→  if (req.method === "OPTIONS") {
 33→    return new Response(null, { headers: corsHeaders });
 34→  }
 35→
 36→  try {
 37→    const authHeader = req.headers.get("Authorization");
 38→    if (!authHeader?.startsWith("Bearer ")) {
 39→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
 40→        status: 401,
 41→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 42→      });
 43→    }
 44→
 45→    const supabase = createClient(
 46→      Deno.env.get("SUPABASE_URL")!,
 47→      Deno.env.get("SUPABASE_ANON_KEY")!,
 48→      { global: { headers: { Authorization: authHeader } } }
 49→    );
 50→
 51→    const token = authHeader.replace("Bearer ", "");
 52→    const { data: claimsData, error: claimsError } = await supabase.auth.getClaims(token);
 53→    if (claimsError || !claimsData?.claims) {
 54→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
 55→        status: 401,
 56→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 57→      });
 58→    }
 59→    const userId = claimsData.claims.sub;
 60→
 61→    const { razorpay_order_id, razorpay_payment_id, razorpay_signature } = await req.json();
 62→
 63→    if (!razorpay_order_id || !razorpay_payment_id || !razorpay_signature) {
 64→      return new Response(JSON.stringify({ error: "Missing payment details" }), {
 65→        status: 400,
 66→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 67→      });
 68→    }
 69→
 70→    const secret = Deno.env.get("RAZORPAY_KEY_SECRET")!;
 71→    const valid = await verifySignature(razorpay_order_id, razorpay_payment_id, razorpay_signature, secret);
 72→
 73→    const serviceClient = createClient(
 74→      Deno.env.get("SUPABASE_URL")!,
 75→      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
 76→    );
 77→
 78→    if (!valid) {
 79→      await serviceClient
 80→        .from("payments")
 81→        .update({ status: "failed", razorpay_payment_id, razorpay_signature })
 82→        .eq("razorpay_order_id", razorpay_order_id)
 83→        .eq("user_id", userId);
 84→
 85→      return new Response(JSON.stringify({ error: "Invalid signature" }), {
 86→        status: 400,
 87→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 88→      });
 89→    }
 90→
 91→    // Get payment record
 92→    const { data: payment, error: payError } = await serviceClient
 93→      .from("payments")
 94→      .select("*")
 95→      .eq("razorpay_order_id", razorpay_order_id)
 96→      .eq("user_id", userId)
 97→      .single();
 98→
 99→    if (payError || !payment) {
100→      return new Response(JSON.stringify({ error: "Payment not found" }), {
101→        status: 404,
102→        headers: { ...corsHeaders, "Content-Type": "application/json" },
103→      });
104→    }
105→
106→    if (payment.status === "paid") {
107→      return new Response(JSON.stringify({ status: "already_processed" }), {
108→        headers: { ...corsHeaders, "Content-Type": "application/json" },
109→      });
110→    }
111→
112→    // Update payment status
113→    await serviceClient
114→      .from("payments")
115→      .update({ status: "paid", razorpay_payment_id, razorpay_signature })
116→      .eq("id", payment.id);
117→
118→    // Add credits to user
119→    const { data: currentProfile } = await serviceClient
120→      .from("profiles")
121→      .select("credits")
122→      .eq("user_id", userId)
123→      .single();
124→
125→    const updatePayload: Record<string, any> = {
126→      credits: (currentProfile?.credits ?? 0) + payment.credits_purchased,
127→    };
128→
129→    // If this is a plan purchase, update the user's plan
130→    if (payment.plan_id) {
131→      const { data: planData } = await serviceClient
132→        .from("plans")
133→        .select("name, billing_type")
134→        .eq("id", payment.plan_id)
135→        .single();
136→      if (planData) {
137→        updatePayload.plan = planData.name;
138→        // Set subscription expiry based on billing type
139→        const now = new Date();
140→        if (planData.billing_type === "yearly") {
141→          now.setFullYear(now.getFullYear() + 1);
142→        } else {
143→          now.setMonth(now.getMonth() + 1);
144→        }
145→        updatePayload.subscription_ends_at = now.toISOString();
146→      }
147→    }
148→
149→    await serviceClient
150→      .from("profiles")
151→      .update(updatePayload)
152→      .eq("user_id", userId);
153→
154→    return new Response(
155→      JSON.stringify({ status: "success", credits_added: payment.credits_purchased }),
156→      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
157→    );
158→  } catch (err: unknown) {
159→    console.error("Error:", err);
160→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
161→      status: 500,
162→      headers: { ...corsHeaders, "Content-Type": "application/json" },
163→    });
164→  }
165→});
