  1→import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
  2→
  3→const corsHeaders = {
  4→  "Access-Control-Allow-Origin": "*",
  5→  "Access-Control-Allow-Headers":
  6→    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
  7→};
  8→
  9→async function verifyWebhookSignature(
 10→  body: string,
 11→  signature: string,
 12→  secret: string
 13→): Promise<boolean> {
 14→  const enc = new TextEncoder();
 15→  const key = await crypto.subtle.importKey(
 16→    "raw",
 17→    enc.encode(secret),
 18→    { name: "HMAC", hash: "SHA-256" },
 19→    false,
 20→    ["sign"]
 21→  );
 22→  const sig = await crypto.subtle.sign("HMAC", key, enc.encode(body));
 23→  const hex = Array.from(new Uint8Array(sig))
 24→    .map((b) => b.toString(16).padStart(2, "0"))
 25→    .join("");
 26→  return hex === signature;
 27→}
 28→
 29→Deno.serve(async (req) => {
 30→  if (req.method === "OPTIONS") {
 31→    return new Response(null, { headers: corsHeaders });
 32→  }
 33→
 34→  try {
 35→    const webhookSecret = Deno.env.get("RAZORPAY_WEBHOOK_SECRET");
 36→    if (!webhookSecret) {
 37→      console.error("RAZORPAY_WEBHOOK_SECRET not configured");
 38→      return new Response(JSON.stringify({ error: "Webhook secret not configured" }), {
 39→        status: 500,
 40→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 41→      });
 42→    }
 43→
 44→    const bodyText = await req.text();
 45→    const signature = req.headers.get("x-razorpay-signature") || "";
 46→
 47→    const valid = await verifyWebhookSignature(bodyText, signature, webhookSecret);
 48→    if (!valid) {
 49→      console.error("Invalid webhook signature");
 50→      return new Response(JSON.stringify({ error: "Invalid signature" }), {
 51→        status: 400,
 52→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 53→      });
 54→    }
 55→
 56→    const payload = JSON.parse(bodyText);
 57→    const event = payload.event;
 58→    const subscriptionEntity = payload.payload?.subscription?.entity;
 59→    const paymentEntity = payload.payload?.payment?.entity;
 60→
 61→    if (!subscriptionEntity) {
 62→      return new Response(JSON.stringify({ status: "ignored", reason: "no subscription entity" }), {
 63→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 64→      });
 65→    }
 66→
 67→    const razorpaySubId = subscriptionEntity.id;
 68→    const notes = subscriptionEntity.notes || {};
 69→    const userId = notes.user_id;
 70→    const planId = notes.plan_id;
 71→
 72→    const serviceClient = createClient(
 73→      Deno.env.get("SUPABASE_URL")!,
 74→      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
 75→    );
 76→
 77→    // Log webhook event
 78→    await serviceClient.from("subscription_webhooks").insert({
 79→      event_type: event,
 80→      razorpay_subscription_id: razorpaySubId,
 81→      razorpay_payment_id: paymentEntity?.id || null,
 82→      payload,
 83→      user_id: userId || null,
 84→      processed: false,
 85→    });
 86→
 87→    if (!userId) {
 88→      console.error("No user_id in subscription notes");
 89→      return new Response(JSON.stringify({ status: "logged", reason: "no user_id in notes" }), {
 90→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 91→      });
 92→    }
 93→
 94→    switch (event) {
 95→      case "subscription.authenticated": {
 96→        // Subscription created, first payment pending - no action needed yet
 97→        console.log(`Subscription authenticated for user ${userId}`);
 98→        break;
 99→      }
100→
101→      case "subscription.charged": {
102→        // Recurring payment successful — add credits and extend expiry
103→        console.log(`Subscription charged for user ${userId}`);
104→
105→        let credits = 0;
106→        let planName = notes.plan_name || "unknown";
107→        let billingType = "monthly";
108→
109→        if (planId) {
110→          const { data: plan } = await serviceClient
111→            .from("plans")
112→            .select("credits, name, billing_type")
113→            .eq("id", planId)
114→            .single();
115→          if (plan) {
116→            credits = plan.credits;
117→            planName = plan.name;
118→            billingType = plan.billing_type;
119→          }
120→        }
121→
122→        // Get current profile
123→        const { data: profile } = await serviceClient
124→          .from("profiles")
125→          .select("credits")
126→          .eq("user_id", userId)
127→          .single();
128→
129→        const now = new Date();
130→        if (billingType === "yearly") {
131→          now.setFullYear(now.getFullYear() + 1);
132→        } else {
133→          now.setMonth(now.getMonth() + 1);
134→        }
135→
136→        await serviceClient
137→          .from("profiles")
138→          .update({
139→            credits: (profile?.credits ?? 0) + credits,
140→            plan: planName,
141→            subscription_ends_at: now.toISOString(),
142→            razorpay_subscription_id: razorpaySubId,
143→          })
144→          .eq("user_id", userId);
145→
146→        // Update payment record
147→        if (paymentEntity?.id) {
148→          await serviceClient
149→            .from("payments")
150→            .update({
151→              status: "paid",
152→              razorpay_payment_id: paymentEntity.id,
153→            })
154→            .eq("razorpay_order_id", razorpaySubId)
155→            .eq("status", "created");
156→        }
157→
158→        break;
159→      }
160→
161→      case "subscription.cancelled": {
162→        // User or system cancelled — will downgrade after current period ends
163→        console.log(`Subscription cancelled for user ${userId}`);
164→        // Don't immediately downgrade — the subscription runs until current_end
165→        // The check-expired-subscriptions cron handles the actual downgrade
166→        break;
167→      }
168→
169→      case "subscription.halted": {
170→        // Payment failed after retries — downgrade immediately
171→        console.log(`Subscription halted for user ${userId}`);
172→        await serviceClient
173→          .from("profiles")
174→          .update({
175→            plan: "free",
176→            subscription_ends_at: null,
177→            razorpay_subscription_id: null,
178→          })
179→          .eq("user_id", userId);
180→        break;
181→      }
182→
183→      case "subscription.pending": {
184→        // Payment retry in progress — log only
185→        console.log(`Subscription pending for user ${userId}`);
186→        break;
187→      }
188→
189→      default:
190→        console.log(`Unhandled subscription event: ${event}`);
191→    }
192→
193→    // Mark as processed
194→    await serviceClient
195→      .from("subscription_webhooks")
196→      .update({ processed: true })
197→      .eq("razorpay_subscription_id", razorpaySubId)
198→      .eq("event_type", event)
199→      .eq("processed", false);
200→
201→    return new Response(
202→      JSON.stringify({ status: "ok", event }),
203→      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
204→    );
205→  } catch (err: unknown) {
206→    console.error("Webhook error:", err);
207→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
208→      status: 500,
209→      headers: { ...corsHeaders, "Content-Type": "application/json" },
210→    });
211→  }
212→});
