44→        headers: { ...corsHeaders, "Content-Type": "application/json" },
45→      });
46→    }
47→
48→    if (!["dismissed", "failed"].includes(reason)) {
49→      return new Response(JSON.stringify({ error: "reason must be 'dismissed' or 'failed'" }), {
50→        status: 400,
51→        headers: { ...corsHeaders, "Content-Type": "application/json" },
52→      });
53→    }
54→
55→    const serviceClient = createClient(
56→      Deno.env.get("SUPABASE_URL")!,
57→      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
58→    );
59→
60→    // Only update if status is still "created" and belongs to this user
61→    const { data, error } = await serviceClient
62→      .from("payments")
63→      .update({ status: reason })
64→      .eq("razorpay_order_id", razorpay_order_id)
65→      .eq("user_id", userId)
66→      .eq("status", "created")
67→      .select("id")
68→      .maybeSingle();
69→
70→    if (error) {
71→      console.error("Update error:", error);
72→      return new Response(JSON.stringify({ error: "Failed to update payment" }), {
73→        status: 500,
74→        headers: { ...corsHeaders, "Content-Type": "application/json" },
75→      });
76→    }
77→
78→    return new Response(
79→      JSON.stringify({ success: true, updated: !!data }),
80→      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
81→    );
82→  } catch (err: unknown) {
83→    console.error("Error:", err);
84→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
85→      status: 500,
86→      headers: { ...corsHeaders, "Content-Type": "application/json" },
87→    });
88→  }
89→});
