  9→// Svix webhook verification
 10→async function verifyWebhookSignature(
 11→  secret: string,
 12→  payload: string,
 13→  headers: { id: string; timestamp: string; signature: string }
 14→): Promise<boolean> {
 15→  try {
 16→    // Decode the base64 secret (strip whsec_ prefix if present)
 17→    const secretBytes = Uint8Array.from(
 18→      atob(secret.startsWith("whsec_") ? secret.slice(6) : secret),
 19→      (c) => c.charCodeAt(0)
 20→    );
 21→
 22→    const toSign = `${headers.id}.${headers.timestamp}.${payload}`;
 23→    const key = await crypto.subtle.importKey(
 24→      "raw",
 25→      secretBytes,
 26→      { name: "HMAC", hash: "SHA-256" },
 27→      false,
 28→      ["sign"]
 29→    );
 30→    const signatureBytes = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(toSign));
 31→    const computedSig = btoa(String.fromCharCode(...new Uint8Array(signatureBytes)));
 32→
 33→    // The signature header can contain multiple signatures separated by spaces
 34→    const signatures = headers.signature.split(" ");
 35→    for (const sig of signatures) {
 36→      const sigValue = sig.startsWith("v1,") ? sig.slice(3) : sig;
 37→      if (sigValue === computedSig) return true;
 38→    }
 39→    return false;
 40→  } catch (e) {
 41→    console.error("Signature verification error:", e);
 42→    return false;
 43→  }
 44→}
 45→
 46→serve(async (req) => {
 47→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 48→
 49→  try {
 50→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 51→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 52→    const WEBHOOK_SECRET = Deno.env.get("DODO_PAYMENTS_WEBHOOK_SECRET");
 53→
 54→    const rawBody = await req.text();
 55→
 56→    // Verify webhook signature if secret is configured
 57→    if (WEBHOOK_SECRET) {
 58→      const webhookId = req.headers.get("webhook-id") || "";
 59→      const webhookTimestamp = req.headers.get("webhook-timestamp") || "";
 60→      const webhookSignature = req.headers.get("webhook-signature") || "";
 61→
 62→      if (!webhookId || !webhookTimestamp || !webhookSignature) {
 63→        return new Response("Missing webhook headers", { status: 400, headers: corsHeaders });
 64→      }
 65→
 66→      // Check timestamp is within 5 minutes
 67→      const now = Math.floor(Date.now() / 1000);
 68→      const ts = parseInt(webhookTimestamp, 10);
 69→      if (Math.abs(now - ts) > 300) {
 70→        return new Response("Webhook timestamp too old", { status: 400, headers: corsHeaders });
 71→      }
 72→
 73→      const valid = await verifyWebhookSignature(WEBHOOK_SECRET, rawBody, {
 74→        id: webhookId,
 75→        timestamp: webhookTimestamp,
 76→        signature: webhookSignature,
 77→      });
 78→
 79→      if (!valid) {
 80→        console.error("Invalid webhook signature");
 81→        return new Response("Invalid signature", { status: 400, headers: corsHeaders });
 82→      }
 83→    }
 84→
 85→    const event = JSON.parse(rawBody);
 86→    const eventType = event.type || event.event_type || "unknown";
 87→    const payload = event.data || event.payload || event;
 88→
 89→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 90→
 91→    // Log the webhook event
 92→    const logEntry: Record<string, unknown> = {
 93→      event_type: eventType,
 94→      payload: event,
 95→      gateway: "dodo",
 96→      processed: false,
 97→    };
 98→
 99→    if (payload?.payment_id) logEntry.dodo_subscription_id = payload.subscription_id || null;
100→
101→    await supabase.from("subscription_webhooks").insert(logEntry);
102→
103→    // Process based on event type
104→    if (eventType === "payment.succeeded" || eventType === "payment_succeeded") {
105→      const paymentId = payload.payment_id;
106→      if (!paymentId) {
107→        console.error("No payment_id in webhook payload");
108→        return new Response("OK", { status: 200, headers: corsHeaders });
109→      }
110→
111→      // Find the payment record
112→      const { data: payment } = await supabase
113→        .from("payments")
114→        .select("*")
115→        .eq("dodo_payment_id", paymentId)
116→        .single();
117→
118→      if (payment && payment.status !== "paid") {
119→        // Mark as paid
120→        await supabase
121→          .from("payments")
122→          .update({ status: "paid" })
123→          .eq("id", payment.id);
124→
125→        // Add credits to user profile
126→        await supabase
127→          .from("profiles")
128→          .update({
129→            credits: supabase.rpc ? undefined : undefined,
130→          })
131→          .eq("user_id", payment.user_id);
132→
133→        // Use raw SQL-like approach: increment credits
134→        const { data: profile } = await supabase
135→          .from("profiles")
136→          .select("credits")
137→          .eq("user_id", payment.user_id)
138→          .single();
139→
140→        if (profile) {
141→          await supabase
142→            .from("profiles")
143→            .update({ credits: profile.credits + payment.credits_purchased })
144→            .eq("user_id", payment.user_id);
145→        }
146→
147→        // If it's a plan purchase, activate the plan
148→        if (payment.plan_id) {
149→          const { data: plan } = await supabase
150→            .from("plans")
151→            .select("name, billing_type")
152→            .eq("id", payment.plan_id)
153→            .single();
154→
155→          if (plan) {
156→            const now = new Date();
157→            const endsAt = new Date(now);
158→            if (plan.billing_type === "yearly") {
159→              endsAt.setFullYear(endsAt.getFullYear() + 1);
160→            } else {
161→              endsAt.setMonth(endsAt.getMonth() + 1);
162→            }
163→
164→            await supabase
165→              .from("profiles")
166→              .update({
167→                plan: plan.name,
168→                subscription_ends_at: endsAt.toISOString(),
169→                dodo_subscription_id: payload.subscription_id || null,
170→              })
171→              .eq("user_id", payment.user_id);
172→          }
173→        }
174→
175→        // Mark webhook as processed
176→        await supabase
177→          .from("subscription_webhooks")
178→          .update({ processed: true, user_id: payment.user_id })
179→          .eq("event_type", eventType)
180→          .eq("processed", false)
181→          .order("created_at", { ascending: false })
182→          .limit(1);
183→      }
184→    } else if (eventType === "payment.failed" || eventType === "payment_failed") {
185→      const paymentId = payload.payment_id;
186→      if (paymentId) {
187→        await supabase
188→          .from("payments")
189→          .update({ status: "failed" })
190→          .eq("dodo_payment_id", paymentId);
191→      }
192→    } else if (eventType === "subscription.active" || eventType === "subscription_active") {
193→      // Subscription activated — handled similarly to payment.succeeded for plan
194→      console.log("Subscription active event:", payload);
195→    } else if (eventType === "subscription.renewed" || eventType === "subscription_renewed") {
196→      // Recurring payment — add credits + extend expiry
197→      const subscriptionId = payload.subscription_id;
198→      if (subscriptionId) {
199→        const { data: profile } = await supabase
200→          .from("profiles")
201→          .select("user_id, plan, credits")
202→          .eq("dodo_subscription_id", subscriptionId)
203→          .single();
204→
205→        if (profile) {
206→          // Look up plan credits
207→          const { data: plan } = await supabase
208→            .from("plans")
209→            .select("credits, billing_type")
210→            .eq("name", profile.plan)
211→            .single();
212→
213→          if (plan) {
214→            const endsAt = new Date();
215→            if (plan.billing_type === "yearly") {
216→              endsAt.setFullYear(endsAt.getFullYear() + 1);
217→            } else {
218→              endsAt.setMonth(endsAt.getMonth() + 1);
219→            }
220→
221→            await supabase
222→              .from("profiles")
223→              .update({
224→                credits: profile.credits + plan.credits,
225→                subscription_ends_at: endsAt.toISOString(),
226→              })
227→              .eq("user_id", profile.user_id);
228→          }
229→        }
230→      }
231→    } else if (
232→      eventType === "subscription.cancelled" ||
233→      eventType === "subscription_cancelled" ||
234→      eventType === "subscription.on_hold" ||
235→      eventType === "subscription.failed"
236→    ) {
237→      const subscriptionId = payload.subscription_id;
238→      if (subscriptionId) {
239→        // For cancelled: let expiry handle downgrade
240→        // For on_hold/failed: downgrade immediately
241→        if (eventType.includes("on_hold") || eventType.includes("failed")) {
242→          await supabase
243→            .from("profiles")
244→            .update({
245→              plan: "free",
246→              dodo_subscription_id: null,
247→              subscription_ends_at: null,
248→            })
249→            .eq("dodo_subscription_id", subscriptionId);
250→        }
251→      }
252→    }
253→
254→    return new Response("OK", { status: 200, headers: corsHeaders });
255→  } catch (err: unknown) {
256→    console.error("dodo-webhook error:", err);
257→    return new Response("Internal error", { status: 500, headers: corsHeaders });
258→  }
259→});
