 1→import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
 2→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
 3→
 4→const corsHeaders = {
 5→  "Access-Control-Allow-Origin": "*",
 6→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
 7→};
 8→
 9→serve(async (req) => {
10→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
11→
12→  try {
13→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
14→    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
15→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
16→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
17→
18→    if (!DODO_API_KEY) {
19→      return new Response(JSON.stringify({ error: "Dodo Payments not configured" }), {
20→        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
21→      });
22→    }
23→
24→    const authHeader = req.headers.get("Authorization");
25→    if (!authHeader) {
26→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
27→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
28→      });
29→    }
30→
31→    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
32→      global: { headers: { Authorization: authHeader } },
33→    });
34→    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
35→    if (userError || !user) {
36→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
37→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
38→      });
39→    }
40→
41→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
42→
43→    // Get user's dodo subscription ID
44→    const { data: profile } = await supabase
45→      .from("profiles")
46→      .select("dodo_subscription_id")
47→      .eq("user_id", user.id)
48→      .single();
49→
50→    if (!profile?.dodo_subscription_id) {
51→      return new Response(JSON.stringify({ error: "No active Dodo subscription found" }), {
52→        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
53→      });
54→    }
55→
56→    // Cancel subscription via Dodo API
57→    const dodoRes = await fetch(
58→      `https://live.dodopayments.com/subscriptions/${profile.dodo_subscription_id}`,
59→      {
60→        method: "PATCH",
61→        headers: {
62→          "Authorization": `Bearer ${DODO_API_KEY}`,
63→          "Content-Type": "application/json",
64→        },
65→        body: JSON.stringify({ status: "cancelled" }),
66→      }
67→    );
68→
69→    if (!dodoRes.ok) {
70→      const errText = await dodoRes.text();
71→      console.error("Dodo cancel error:", dodoRes.status, errText);
72→      return new Response(JSON.stringify({ error: `Failed to cancel: ${errText.slice(0, 200)}` }), {
73→        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
74→      });
75→    }
76→
77→    // Update profile — subscription will remain active until end of period
78→    // The webhook will handle the final downgrade
79→
80→    return new Response(JSON.stringify({ success: true, message: "Subscription will cancel at end of billing period" }), {
81→      headers: { ...corsHeaders, "Content-Type": "application/json" },
82→    });
83→  } catch (err: unknown) {
84→    console.error("cancel-dodo-subscription error:", err);
85→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
86→      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
87→    });
88→  }
89→});
